
import 'dart:convert';
import 'dart:io';
import 'package:flutter/material.dart';
import 'package:shared_preferences/shared_preferences.dart';
import 'package:image_picker/image_picker.dart';
import 'package:pdf/widgets.dart' as pw;
import 'package:printing/printing.dart';

const navy=Color(0xFF123B78), blue=Color(0xFF1769D2);
void main()=>runApp(const SchoolApp());
class SchoolApp extends StatelessWidget{const SchoolApp({super.key});@override Widget build(BuildContext c)=>MaterialApp(title:'School Management',debugShowCheckedModeBanner:false,theme:ThemeData(useMaterial3:true,colorScheme:ColorScheme.fromSeed(seedColor:blue),scaffoldBackgroundColor:const Color(0xfff3f6fb)),home:const Home());}
class Home extends StatefulWidget{const Home({super.key});@override State<Home> createState()=>_HomeState();}
class _HomeState extends State<Home>{
 String school='New Iqra Children Academy'; String? logo; int tab=0; String search='';
 List<Map<String,dynamic>> students=[],teachers=[],fees=[],marks=[],attendance=[];
 final picker=ImagePicker(); final searchC=TextEditingController();
 @override void initState(){super.initState();load();}
 Future<void> load()async{final p=await SharedPreferences.getInstance();setState((){school=p.getString('school')??school;logo=p.getString('logo');students=read(p,'students');teachers=read(p,'teachers');fees=read(p,'fees');marks=read(p,'marks');attendance=read(p,'attendance');});}
 List<Map<String,dynamic>> read(SharedPreferences p,String k)=> (jsonDecode(p.getString(k)??'[]') as List).map((e)=>Map<String,dynamic>.from(e)).toList();
 Future<void> save()async{final p=await SharedPreferences.getInstance();await p.setString('school',school);if(logo!=null)await p.setString('logo',logo!);for(final x in {'students':students,'teachers':teachers,'fees':fees,'marks':marks,'attendance':attendance}.entries){await p.setString(x.key,jsonEncode(x.value));}}
 String val(Map m,String k)=>'${m[k]??''}';
 Map<String,dynamic>? studentByRoll(String r){for(final s in students){if(val(s,'roll').toLowerCase()==r.toLowerCase())return s;}return null;}
 Future<String?> imagePick()async{final x=await picker.pickImage(source:ImageSource.gallery,imageQuality:80);return x?.path;}
 Future<void> settings()async{final c=TextEditingController(text:school);await showDialog(context:context,builder:(d)=>AlertDialog(title:const Text('School Settings'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:c,decoration:const InputDecoration(labelText:'School name')),const SizedBox(height:8),OutlinedButton.icon(onPressed:()async{final x=await imagePick();if(x!=null)setState(()=>logo=x);},icon:const Icon(Icons.image),label:const Text('Select school logo'))]),actions:[TextButton(onPressed:()=>Navigator.pop(d),child:const Text('Cancel')),FilledButton(onPressed:()async{setState(()=>school=c.text.trim().isEmpty?'School Management':c.text.trim());await save();if(d.mounted)Navigator.pop(d);},child:const Text('Save'))]));}
 Future<void> formRecord({required bool student,Map<String,dynamic>? old})async{
 final fields=student?['Student Name','Father Name','Roll Number','Admission Number','Phone Number','Date of Birth','Class (1-10)','Section','Address','Admission Date']:['Teacher Name','Father Name','Phone Number','Date of Birth','Address','Qualification','Subject','Assigned Class','Joining Date','Monthly Salary'];
 final keys=student?['name','father','roll','admission','phone','dob','class','section','address','admitDate']:['name','father','phone','dob','address','qualification','subject','class','joinDate','salary'];
 final ctrls=[for(final k in keys)TextEditingController(text:val(old??{},k))];String? photo=val(old??{},'photo').isEmpty?null:val(old??{},'photo');
 final ok=await showDialog<bool>(context:context,builder:(d)=>StatefulBuilder(builder:(d,setD)=>AlertDialog(title:Text(student?'Student Registration':'Teacher Registration'),content:SizedBox(width:420,height:MediaQuery.of(d).size.height*.62,child:SingleChildScrollView(child:Column(children:[if(student||true)Row(children:[CircleAvatar(radius:34,backgroundImage:photo!=null&&File(photo!).existsSync()?FileImage(File(photo!)):null,child:photo==null?const Icon(Icons.person,size:32):null),const SizedBox(width:12),OutlinedButton.icon(onPressed:()async{final x=await imagePick();if(x!=null)setD(()=>photo=x);},icon:const Icon(Icons.photo),label:const Text('Passport photo'))]),...List.generate(fields.length,(i)=>Padding(padding:const EdgeInsets.only(top:10),child:TextField(controller:ctrls[i],keyboardType:['phone','salary'].contains(keys[i])?TextInputType.number:TextInputType.text,decoration:InputDecoration(labelText:fields[i],border:const OutlineInputBorder()))))]))),actions:[TextButton(onPressed:()=>Navigator.pop(d,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(d,true),child:const Text('Save'))])));
 if(ok==true){final item=<String,dynamic>{for(int i=0;i<keys.length;i++)keys[i]:ctrls[i].text.trim(),'photo':photo};setState((){final list=student?students:teachers;if(old==null)list.add(item);else{final idx=list.indexOf(old);if(idx>=0)list[idx]=item;}});await save();}
 }
 Future<Map<String,String>?> askFields(String title,List<String> labels)async{final cs=[for(final _ in labels)TextEditingController()];return showDialog<Map<String,String>>(context:context,builder:(d)=>AlertDialog(title:Text(title),content:SizedBox(width:400,child:SingleChildScrollView(child:Column(children:[for(int i=0;i<labels.length;i++)Padding(padding:const EdgeInsets.only(bottom:8),child:TextField(controller:cs[i],decoration:InputDecoration(labelText:labels[i],border:const OutlineInputBorder())))]))),actions:[TextButton(onPressed:()=>Navigator.pop(d),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(d,{for(int i=0;i<labels.length;i++)labels[i]:cs[i].text.trim()}),child:const Text('Save'))]));}
 Future<void> feeEntry()async{final m=await askFields('Fee Record',['Roll Number','Month','Fee Due (PKR)','Paid (PKR)','Payment Date','Receipt Number']);if(m==null)return;final s=studentByRoll(m['Roll Number']??'');if(s==null){msg('No student found for that roll number');return;}setState(()=>fees.add({'roll':m['Roll Number'],'month':m['Month'],'due':m['Fee Due (PKR)'],'paid':m['Paid (PKR)'],'date':m['Payment Date'],'receipt':m['Receipt Number']}));await save();}
 Future<void> markEntry()async{final m=await askFields('Marks Entry',['Roll Number','Class','Exam / Term','Subject','Total Marks','Obtained Marks']);if(m==null)return;if(studentByRoll(m['Roll Number']??'')==null){msg('Student roll number not found');return;}setState(()=>marks.add({'roll':m['Roll Number'],'class':m['Class'],'exam':m['Exam / Term'],'subject':m['Subject'],'total':m['Total Marks'],'obtained':m['Obtained Marks']}));await save();}
 Future<void> attendEntry()async{final m=await askFields('Attendance',['Roll Number','Date (YYYY-MM-DD)','Status (Present/Absent)']);if(m==null)return;if(studentByRoll(m['Roll Number']??'')==null){msg('Student roll number not found');return;}setState(()=>attendance.add({'roll':m['Roll Number'],'date':m['Date (YYYY-MM-DD)'],'status':m['Status (Present/Absent)']}));await save();}
 void msg(String s)=>ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(s)));
 Future<void> printDoc(String type,Map<String,dynamic> s)async{final r=val(s,'roll');final related=marks.where((m)=>val(m,'roll')==r).toList();final f=fees.where((m)=>val(m,'roll')==r).toList();final doc=pw.Document();doc.addPage(pw.Page(build:(ctx)=>pw.Column(crossAxisAlignment:pw.CrossAxisAlignment.start,children:[pw.Text(school,style:pw.TextStyle(fontSize:24,fontWeight:pw.FontWeight.bold)),pw.SizedBox(height:8),pw.Text(type,style:pw.TextStyle(fontSize:20,fontWeight:pw.FontWeight.bold)),pw.Divider(),pw.Text('Name: ${val(s,'name')}'),pw.Text('Father: ${val(s,'father')}'),pw.Text('Roll: $r  Class: ${val(s,'class')}'),pw.Text('DOB: ${val(s,'dob')}'),pw.Text('Address: ${val(s,'address')}'),pw.SizedBox(height:12),if(type.contains('DMC')||type.contains('Result'))pw.Table.fromTextArray(headers:['Subject','Total','Obtained'],data:related.map((m)=>[val(m,'subject'),val(m,'total'),val(m,'obtained')]).toList()),if(type.contains('Fee'))pw.Table.fromTextArray(headers:['Month','Due','Paid','Date'],data:f.map((m)=>[val(m,'month'),val(m,'due'),val(m,'paid'),val(m,'date')]).toList()),if(type.contains('DMC'))pw.Text('Percent: ${percent(related)}%'),pw.SizedBox(height:24),pw.Text('Principal Signature: __________________')])));await Printing.layoutPdf(onLayout:(format)=>doc.save());}
 String percent(List<Map<String,dynamic>> rows){double a=0,b=0;for(final m in rows){a+=double.tryParse(val(m,'obtained'))??0;b+=double.tryParse(val(m,'total'))??0;}return b==0?'0.00':(a/b*100).toStringAsFixed(2);}
 Widget header()=>Container(padding:const EdgeInsets.all(16),decoration:BoxDecoration(color:navy,borderRadius:BorderRadius.circular(18)),child:Row(children:[CircleAvatar(backgroundColor:Colors.white,backgroundImage:logo!=null&&File(logo!).existsSync()?FileImage(File(logo!)):null,child:logo==null?const Icon(Icons.school,color:blue):null),const SizedBox(width:12),Expanded(child:Text(school,style:const TextStyle(color:Colors.white,fontSize:18,fontWeight:FontWeight.bold))),IconButton(onPressed:settings,icon:const Icon(Icons.settings,color:Colors.white))]));
 Widget dashboard()=>ListView(padding:const EdgeInsets.all(14),children:[header(),const SizedBox(height:12),Wrap(spacing:10,runSpacing:10,children:[stat('Students',students.length),stat('Teachers',teachers.length),stat('Fee collected',fees.fold<double>(0,(a,e)=>a+(double.tryParse(val(e,'paid'))??0)).toStringAsFixed(0)),stat('Fee balance',fees.fold<double>(0,(a,e)=>a+((double.tryParse(val(e,'due'))??0)-(double.tryParse(val(e,'paid'))??0))).toStringAsFixed(0))]),const SizedBox(height:12),TextField(controller:searchC,onChanged:(v)=>setState(()=>search=v),decoration:const InputDecoration(prefixIcon:Icon(Icons.search),labelText:'Search student by roll number',border:OutlineInputBorder())),if(search.isNotEmpty)...students.where((s)=>val(s,'roll').toLowerCase().contains(search.toLowerCase())).map((s)=>studentTile(s)),const SizedBox(height:12),_action('Register Student',Icons.person_add,()=>formRecord(student:true)),_action('Register Teacher',Icons.co_present,()=>formRecord(student:false)),_action('Fee Entry',Icons.payments,feeEntry),_action('Marks Entry / DMC',Icons.assignment,markEntry),_action('Attendance',Icons.fact_check,attendEntry)]);
 Widget stat(String t,int n)=>Container(width:MediaQuery.of(context).size.width/2-22,padding:const EdgeInsets.all(14),decoration:BoxDecoration(color:Colors.white,borderRadius:BorderRadius.circular(14)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(t),Text('$n',style:const TextStyle(fontSize:22,fontWeight:FontWeight.bold))]));
 Widget _action(String t,IconData i,VoidCallback f)=>Card(child:ListTile(leading:Icon(i,color:blue),title:Text(t),trailing:const Icon(Icons.chevron_right),onTap:f));
 Widget studentTile(Map<String,dynamic>s)=>Card(child:ListTile(leading:CircleAvatar(backgroundImage:val(s,'photo').isNotEmpty&&File(val(s,'photo')).existsSync()?FileImage(File(val(s,'photo'))):null,child:val(s,'photo').isEmpty?const Icon(Icons.person):null),title:Text('${val(s,'name')} • Roll ${val(s,'roll')}'),subtitle:Text('Class ${val(s,'class')} | Father: ${val(s,'father')}'),onTap:()=>studentActions(s)));
 Future<void> studentActions(Map<String,dynamic>s)async{await showModalBottomSheet(context:context,builder:(d)=>SafeArea(child:Wrap(children:[ListTile(title:Text('${val(s,'name')} — ${val(s,'roll')}',style:const TextStyle(fontWeight:FontWeight.bold))),ListTile(leading:const Icon(Icons.edit),title:const Text('Edit student'),onTap:(){Navigator.pop(d);formRecord(student:true,old:s);}),for(final t in ['Student ID Card','DMC / Result Card','Fee Statement','Character Certificate'])ListTile(leading:const Icon(Icons.picture_as_pdf),title:Text(t),onTap:(){Navigator.pop(d);printDoc(t,s);})])));}
 Widget records(bool isS){final list=isS?students:teachers;return ListView(padding:const EdgeInsets.all(12),children:[TextField(onChanged:(v)=>setState(()=>search=v),decoration:InputDecoration(prefixIcon:const Icon(Icons.search),labelText:isS?'Search by roll number':'Search teacher',border:const OutlineInputBorder())),const SizedBox(height:8),...list.where((m)=>!isS||search.isEmpty||val(m,'roll').contains(search)).map((m)=>Card(child:ListTile(leading:CircleAvatar(child:Icon(isS?Icons.school:Icons.person)),title:Text(val(m,'name')),subtitle:Text(isS?'Roll ${val(m,'roll')} • Class ${val(m,'class')}':'${val(m,'subject')} • ${val(m,'phone')}'),onTap:isS?()=>studentActions(m):null,trailing:IconButton(icon:const Icon(Icons.delete_outline),onPressed:()async{setState(()=>list.remove(m));await save();}))))]);}
 Widget reportPage()=>ListView(padding:const EdgeInsets.all(12),children:[_action('Create DMC / Result PDF',Icons.assignment,markEntry),_action('Fee record',Icons.receipt,feeEntry),_action('Student records',Icons.people,()=>setState(()=>tab=1)),_action('Attendance entry',Icons.fact_check,attendEntry),...students.map(studentTile)]);
 @override Widget build(BuildContext c){final pages=[dashboard(),records(true),records(false),ListView(padding:const EdgeInsets.all(12),children:[_action('Mark attendance by roll number',Icons.fact_check,attendEntry),...attendance.map((a)=>ListTile(title:Text('Roll ${val(a,'roll')} • ${val(a,'date')}'),subtitle:Text(val(a,'status'))))]),reportPage()];return Scaffold(appBar:AppBar(title:Text(tab==0?school:['Home','Students','Teachers','Attendance','Reports'][tab],maxLines:1,overflow:TextOverflow.ellipsis),backgroundColor:navy,foregroundColor:Colors.white),body:pages[tab],floatingActionButton:tab==1||tab==2?FloatingActionButton(onPressed:()=>formRecord(student:tab==1),child:const Icon(Icons.add)):null,bottomNavigationBar:NavigationBar(selectedIndex:tab,onDestinationSelected:(i)=>setState(()=>tab=i),destinations:const[NavigationDestination(icon:Icon(Icons.home),label:'Home'),NavigationDestination(icon:Icon(Icons.people),label:'Students'),NavigationDestination(icon:Icon(Icons.person),label:'Teachers'),NavigationDestination(icon:Icon(Icons.fact_check),label:'Attendance'),NavigationDestination(icon:Icon(Icons.bar_chart),label:'Reports')]));}
}
